mapper.select:
select 'XWXT' as systemCode, -- 来源系统 CASE WHEN gf.vc_chuzrwtdlr='海通恒信国际融资租赁股份有限公司' THEN '01-C0001' WHEN gf.vc_chuzrwtdlr='海通恒信国际融资租赁（天津）有限公司' THEN '02-C0001' WHEN gf.vc_chuzrwtdlr='海通恒信小微融资租赁（上海）有限公司' THEN '80001' WHEN gf.vc_chuzrwtdlr='海通恒运融资租赁（上海）有限公司' THEN '30001' END AS orgId, -- gf.vc_chuzrwtdlr 签约主体名称, ht.vc_hetbh as contractCode, -- 合同编号 -- ht.vc_hetmc 合同名称, ht.vc_kehbh as clientCode, -- 客户编号 -- czr.vc_kehmc 客户名称, cw.nu_qix as periods, -- 期数 -- ht.dt_shijqzr 业务日期, nvl(zjjh.dt_chengfrq,cw.dt_chengfrq) as planDate, -- 计划还款日 nvl(zjjh.dec_zuj,0) as rentAmount, -- "归还租金（含税额）" nvl(zjjh.dec_benj,0) as principalAmount , -- "归还本金（含税额）" nvl(zjjh.dec_zux,0) as interestAmount, -- "归还利息（含税额）" -- nvl(zjjh.dec_zuj,0) "归还租金（不含税额）", -- nvl(zjjh.dec_benj,0) "归还本金（不含税额）", -- nvl(zjjh.dec_zux,0) "归还利息（不含税额）", hlzt.vc_mingc as recaptureStatus , -- 回笼状态 zjjh.dec_nianll as sourceIrrRate, -- decode(nvl(zjjh.vc_jihzt,'0'), '0', 0, trunc(sysdate) - zjjh.dt_chengfrq) 逾期天数, cw.dec_jingll as cashFlow from jbfs.bz_hetjbxx ht join jbfs.bz_hetgf gf on gf.vc_hetbh = ht.vc_hetbh join jbfs.cm_jigkh czr on czr.vc_kehbh = ht.vc_kehbh join jbfs.fm_jiaoyjg jg on jg.vc_cesztbh = ht.vc_hetbh left join jbfs.fm_jiaoyjgcwxjl cw on jg.vc_cesztbh = cw.vc_cesztbh left join jbfs.fm_jiaoyjgzjjh zjjh on zjjh.vc_cesztbh = cw.vc_cesztbh and zjjh.nu_qix = cw.nu_duiyzjbdqx left join jbfs.ba_shujzd hlzt on hlzt.vc_zhi = zjjh.vc_jihzt and hlzt.vc_fujdid = 'huilzt' where ht.vc_hetzt = '31'
and ht.vc_hetbh = #{params.contractCode}
order by ht.vc_hetbh, nvl(zjjh.dt_chengfrq,cw.dt_chengfrq)

WITH table1 AS ( SELECT CONTRACT_ID FROM jbfs.rpt_accmonth_firr_new GROUP BY contract_id HAVING TRUNC(max(PLAN_DATE)) >= TRUNC(TO_DATE('2023-01-01', 'YYYY-MM-DD')) ) SELECT CASE WHEN c.vc_kehmc='海通恒信国际融资租赁股份有限公司' THEN '01-C0001' WHEN c.vc_kehmc='海通恒信国际融资租赁（天津）有限公司' THEN '02-C0001' WHEN c.vc_kehmc='海通恒信小微融资租赁（上海）有限公司' THEN '80001' WHEN c.vc_kehmc='海通恒运融资租赁（上海）有限公司' THEN '30001' END AS orgId, 'XWXT' as systemCode, -- 业务系统编号 a.contract_id as contractCode, --合同编号 a.plan_list as periods, -- 期项 max(a.plan_date) as planDate, -- 承付日期 sum(a.rent) as rentAmount, --租金 sum(a.net_flow) as cashFlow, --净流量 sum(a.naf_cut) as principalAmount, --本金 sum(a.interest) as interestAmount --租息 -- 签约主体 -- IRR Rate -- a.inter_day nu_interday, -- 当期承付日期与上期承付日期相差的天数 -- a.interest_day dec_rilx, --日利息 -- a.interest_date dt_dangqzhyt, -- 当期最后一天 -- a.up_day nu_upday, --当期承付日期距上月最后一天的天数 -- a.down_day nu_downday, --当期承付日期距当月最后一天的天数 -- a.interest_cal dec_hanslx, -- 含税利息 -- a.interest_cal_aftertax dec_buhslx, --不含税利息 -- SYSDATE dt_chuangjsj -- 创建时间 FROM jbfs.rpt_accmonth_firr_new a INNER JOIN table1 d ON a.CONTRACT_ID = d.CONTRACT_ID LEFT JOIN jbfs.bz_hetgf b ON a.CONTRACT_ID = b.VC_HETBH LEFT JOIN jbfs.cm_jigkh c on b.vc_chuzr = c.vc_kehbh and c.CH_YOUXBS = '0' where c.vc_kehmc is not null
and a.contract_id = #{params.contractCode}
group by a.contract_id, a.plan_list, to_char(a.plan_date, 'yyyy-MM'), c.vc_kehmc order by a.contract_id, a.plan_list

WITH table1 AS ( SELECT CONTRACT_ID FROM jbfs.rpt_accmonth_firr_new GROUP BY contract_id HAVING TRUNC(max(PLAN_DATE)) >= TRUNC(TO_DATE('2023-01-01', 'YYYY-MM-DD')) ) SELECT CASE WHEN c.vc_kehmc='海通恒信国际融资租赁股份有限公司' THEN '01-C0001' WHEN c.vc_kehmc='海通恒信国际融资租赁（天津）有限公司' THEN '02-C0001' WHEN c.vc_kehmc='海通恒信小微融资租赁（上海）有限公司' THEN '80001' WHEN c.vc_kehmc='海通恒运融资租赁（上海）有限公司' THEN '30001' END AS orgId, 'XWXT' as systemCode, -- 业务系统编号 a.contract_id as contractCode, --合同编号 a.plan_list as periods, -- 期项 a.plan_date as planDate, -- 承付日期 a.rent as rentAmount, --租金 a.net_flow as cashFlow, --净流量 a.naf_cut as principalAmount, --本金 a.interest as interestAmount --租息 -- 签约主体 -- IRR Rate -- a.inter_day nu_interday, -- 当期承付日期与上期承付日期相差的天数 -- a.interest_day dec_rilx, --日利息 -- a.interest_date dt_dangqzhyt, -- 当期最后一天 -- a.up_day nu_upday, --当期承付日期距上月最后一天的天数 -- a.down_day nu_downday, --当期承付日期距当月最后一天的天数 -- a.interest_cal dec_hanslx, -- 含税利息 -- a.interest_cal_aftertax dec_buhslx, --不含税利息 -- SYSDATE dt_chuangjsj -- 创建时间 FROM jbfs.rpt_accmonth_firr_new a INNER JOIN table1 d ON a.CONTRACT_ID = d.CONTRACT_ID LEFT JOIN jbfs.bz_hetgf b ON a.CONTRACT_ID = b.VC_HETBH LEFT JOIN jbfs.cm_jigkh c on b.vc_chuzr = c.vc_kehbh and c.CH_YOUXBS = '0' where c.vc_kehmc is not null
and a.contract_id = #{params.contractCode}
ORDER BY a.contract_id, a.plan_list

--TA余额+租金余额 SELECT bz_hetjbxx.vc_hetbh contract_code,--合同编号 inter_orgcode.org_name AS org_id,--签约主体 --inter_orgcode.cust_id AS qyztgs, --bz_hetjbxx.dt_shijqzr, --shifyzx.vc_mingc AS vc_shifyzx, --inter_custid_join.cust_id_f, ba_hetztzd.vc_zhuangtmc contract_status,--合同状态 bz_hetjbxx.vc_kehbh client_code,--客户编号 cm_jigkh.vc_kehmc client_name,--客户名称 --bb_getBadDays('1900-01-01', --to_char(SYSDATE, 'yyyy-mm-dd'), --bz_hetjbxx.vc_hetbh) AS badDays, ta_bal.vc_wangybh ebank_serial_number,--业务系统网银编号/批次号 ta_memo.vc_beiz operation_remark, --运营部备注 --fm_wangysj.dt_daozsj, fm_wangysj.vc_fukkh ebank_client_name,--网银付款人名称 fm_wangysj.vc_suosgs bank_org_id,--网银到账主体 --zulxgbz.vc_mingc AS ch_zulxgbz, --CASE --WHEN dt_shijqzr >= to_date('2009-04-01', 'yyyy/mm/dd') --OR vc_zhuangtmc = '合同签约' THEN 'New' -- ELSE 'Legacy' --END Portfolio, nvl(ta_bal.ta_bal, 0) ta_excess_balance--TA/溢存款余额 --t2.rent - nvl(t3.rent, 0) as 租金余额--应收租金余额 --ta_bal.ta_caozrq FROM ( SELECT vc_hetbh, vc_wangybh, SUM(dec_shouzje) ta_bal, MIN(dt_chuangjsj) ta_caozrq FROM jbfs.fm_shissf fm_shissf WHERE vc_feiylx = '206' AND dt_huijclr < to_date(#{queryDate},'yyyy-mm-dd') + 1 GROUP BY vc_hetbh, vc_wangybh) ta_bal LEFT JOIN ( SELECT fm_shissf.vc_hetbh, fm_shissf.vc_wangybh, fm_shissf.vc_beiz FROM jbfs.fm_shissf fm_shissf INNER JOIN ( SELECT vc_hetbh, vc_wangybh, MAX(nu_id) id FROM jbfs.fm_shissf fm_shissf WHERE vc_feiylx = '206' AND dt_huijclr < to_date(#{queryDate},'yyyy-mm-dd') + 1 GROUP BY vc_hetbh, vc_wangybh) a ON a.vc_hetbh = fm_shissf.vc_hetbh AND a.vc_wangybh = fm_shissf.vc_wangybh AND a.id = fm_shissf.nu_id) ta_memo ON ta_memo.vc_hetbh = ta_bal.vc_hetbh AND ta_memo.vc_wangybh = ta_bal.vc_wangybh LEFT JOIN jbfs.bz_hetjbxx bz_hetjbxx ON bz_hetjbxx.vc_hetbh = ta_bal.vc_hetbh LEFT JOIN jbfs.bz_hetgf bz_hetgf ON bz_hetgf.vc_hetbh = bz_hetjbxx.vc_hetbh LEFT JOIN jbfs.inter_orgcode inter_orgcode ON inter_orgcode.cust_id = bz_hetgf.vc_chuzr LEFT JOIN jbfs.cm_jigkh cm_jigkh ON cm_jigkh.vc_kehbh = bz_hetjbxx.vc_kehbh LEFT JOIN jbfs.inter_custid_join inter_custid_join ON inter_custid_join.cust_id_b = bz_hetjbxx.vc_kehbh LEFT JOIN jbfs.fm_wangysj fm_wangysj ON fm_wangysj.vc_wangybh = ta_bal.vc_wangybh LEFT JOIN jbfs.ba_hetztzd ba_hetztzd ON ba_hetztzd.vc_zhuangtbh = bz_hetjbxx.vc_hetzt LEFT JOIN jbfs.ba_shujzd shifyzx ON bz_hetjbxx.vc_shifyzx = shifyzx.vc_zhi AND shifyzx.vc_fujdid = 'flag' LEFT JOIN jbfs.ba_shujzd zulxgbz ON fm_wangysj.ch_zulxgbz = zulxgbz.vc_zhi AND zulxgbz.vc_fujdid = 'flag' --LEFT JOIN (SELECT vc_cesztbh, SUM(dec_zuj) rent, SUM(dec_zux) interest --FROM fm_jiaoyjgzjjh --GROUP BY vc_cesztbh) t2 --ON bz_hetjbxx.vc_hetbh = t2.vc_cesztbh --LEFT JOIN (SELECT vc_hetbh, SUM(dec_huilzj) rent, SUM(dec_huilzx) interest --FROM fm_zujhl --WHERE nvl(dt_huijclr, dt_huilrq) < to_date('会计回笼截止日期入参','yyyy/mm/dd') + 1 --会计回笼截止日期入参 --GROUP BY vc_hetbh) t3 --ON bz_hetjbxx.vc_hetbh = t3.vc_hetbh WHERE nvl(ta_bal.ta_bal, 0) > 0
--AND bz_hetjbxx.vc_shifyzx = ?{shifyzx}
-- AND inter_orgcode.cust_id IN (?{qianyzhtgs})
